<script setup>
import {computed,onBeforeUnmount,ref,watch} from 'vue';
import axios from 'axios';
import {ChevronLeft,RefreshCw,Search,ArrowUpRight} from '@lucide/vue';
import MobileIdentityAvatar from './MobileIdentityAvatar.vue';
import {formatPhoneForDisplay} from '../utils/phoneDisplay.js';
const props=defineProps({apiBase:String,sessionToken:String,visible:{type:Boolean,default:true},agencies:{type:Array,default:()=>[]},candidateId:[String,Number],initialAgencyId:[String,Number]});
const emit=defineEmits(['open-full','compose-email']);const agencyId=ref('all'),view=ref('current'),query=ref(''),rows=ref([]),candidate=ref(null),selected=ref(null),loading=ref(false),error=ref('');let version=0,listVersion=0,loadedAt=0,notificationKey='';
const config=()=>({headers:{'X-Quick-View-Session':props.sessionToken},withCredentials:true});const phone=computed(()=>formatPhoneForDisplay(candidate.value?.phone));const date=value=>value?new Intl.DateTimeFormat(undefined,{weekday:'short',month:'short',day:'numeric',year:'numeric'}).format(new Date(value)):'';
async function load(force=false){if(!props.visible||!props.sessionToken||!force&&Date.now()-loadedAt<60000)return;const id=++listVersion;loading.value=!selected.value;error.value='';try{const{data}=await axios.get(`${props.apiBase}/applicants`,{...config(),params:{agencyId:agencyId.value,view:view.value,q:query.value}});if(id!==listVersion)return;rows.value=data.candidates||[];loadedAt=Date.now();}catch(e){if(id!==listVersion)return;if([401,403,423].includes(e.response?.status))rows.value=[];error.value=e.response?.data?.error?.message||'Applicants could not load.';}finally{if(id===listVersion&&!selected.value)loading.value=false;}}
async function open(row){const id=++version;selected.value=row;candidate.value=null;loading.value=true;error.value='';try{const{data}=await axios.get(`${props.apiBase}/applicants/${row.id}`,{...config(),params:{agencyId:row.agencyId}});if(id===version)candidate.value=data.candidate;}catch(e){if(id===version)error.value=e.response?.data?.error?.message||'This applicant could not open.';}finally{if(id===version)loading.value=false;}}
function back(){version++;selected.value=null;candidate.value=null;error.value='';loading.value=false;}
function full(){const row=candidate.value||selected.value;emit('open-full',{kind:'applicants',agencyId:row?.agencyId||props.agencies[0]?.id,candidateId:row?.id});}
watch(()=>props.visible,value=>{if(value)void load();},{immediate:true});watch([agencyId,view],()=>load(true));function openNotification(){if(!props.visible||!props.candidateId||!props.agencies.length)return;const match=props.initialAgencyId?props.agencies.find(row=>Number(row.id)===Number(props.initialAgencyId)):props.agencies.length===1?props.agencies[0]:null;if(!match)return;const key=`${match.id}:${props.candidateId}`;if(notificationKey===key)return;notificationKey=key;void open({id:props.candidateId,agencyId:match.id});}watch(()=>[props.candidateId,props.initialAgencyId,props.agencies,props.visible],openNotification,{immediate:true,deep:true});watch(()=>props.sessionToken,()=>{version++;listVersion++;notificationKey='';loadedAt=0;rows.value=[];back();void load();});onBeforeUnmount(()=>{version++;listVersion++;});
</script>
<template><section class="mobile-applicants"><header><button v-if="selected" @click="back"><ChevronLeft :size="16"/>Back</button><h2>People Operations</h2><button aria-label="Refresh applicants" :disabled="loading" @click="selected?open(selected):load(true)"><RefreshCw :size="17"/></button></header><template v-if="!selected"><nav><button :aria-pressed="view==='current'" @click="view='current'">Current applicants</button><button :aria-pressed="view==='recent'" @click="view='recent'">Recent applications</button></nav><form class="filters" @submit.prevent="load(true)"><select v-if="agencies.length>1" v-model="agencyId" aria-label="Applicant agency"><option value="all">All agencies</option><option v-for="agency in agencies" :key="agency.id" :value="agency.id">{{agency.name}}</option></select><input type="search" v-model="query" aria-label="Search applicants" placeholder="Find an applicant"/><button aria-label="Search applicants"><Search :size="16"/></button></form><article v-for="row in rows" :key="`${row.agencyId}:${row.id}`"><button class="applicant-row" @click="open(row)"><MobileIdentityAvatar :name="row.name" :agency-icon="row.agencyLogoUrl"/><span><strong>{{row.name}}<small v-if="row.isNew" class="new">New</small></strong><small>{{row.role||'Applicant'}} · {{row.stageLabel}}</small><small>{{row.agencyName}}<template v-if="row.submittedAt"> · {{date(row.submittedAt)}}</template></small></span></button></article><p v-if="!loading&&!rows.length&&!error">No applicants in this view.</p></template><template v-if="candidate"><div class="candidate-heading"><MobileIdentityAvatar :name="candidate.name" :agency-icon="candidate.agencyLogoUrl"/><div><h3>{{candidate.name}}</h3><p>{{candidate.agencyName}} · {{candidate.stageLabel}}</p><p>{{candidate.role}}</p></div></div><div class="candidate-actions"><button v-if="candidate.email" @click="emit('compose-email',{to:candidate.email})">{{candidate.email}}</button><a v-if="phone.telHref" :href="phone.telHref">{{phone.display}}</a><button @click="full"><ArrowUpRight :size="16"/>Full hiring workspace</button></div><h3>Applications</h3><article class="application" v-for="application in candidate.applications" :key="application.submissionId"><strong>{{application.jobTitle}}</strong><small>{{date(application.submittedAt)}}</small><p v-if="application.coverLetterPreview">{{application.coverLetterPreview}}</p></article><p v-if="!candidate.applications.length">No submitted applications are on file.</p><p v-if="candidate.interview?.start">Interview: {{date(candidate.interview.start)}} · {{candidate.interview.status}}</p></template><p v-if="loading" role="status">{{selected?'Opening applicant…':'Loading applicants…'}}</p><p v-if="error" role="alert">{{error}}</p></section></template>
<style scoped>
.mobile-applicants{background:#fff;color:#203b5b;border:1px solid #dce5f2;border-radius:16px;overflow:hidden;font:14px/1.5 system-ui;min-width:0}.mobile-applicants header{display:flex;align-items:center;gap:8px;padding:12px}.mobile-applicants h2{font-size:17px;margin:0;flex:1}.mobile-applicants button,.mobile-applicants a{font:inherit;background:#f4f7fd;border:1px solid #d8e2f1;border-radius:9px;color:#2b527d;padding:9px;min-height:40px;display:inline-flex;gap:5px;align-items:center;justify-content:center;cursor:pointer;user-select:none;-webkit-user-select:none}.mobile-applicants nav{display:flex;gap:6px;padding:5px 12px;overflow:auto}.mobile-applicants nav button{white-space:nowrap}.mobile-applicants [aria-pressed=true]{background:#eaf1ff;color:#2058d8}.filters{display:flex;flex-wrap:wrap;gap:7px;padding:12px}.filters input,.filters select{min-width:0;max-width:100%;font:16px system-ui;border:1px solid #cad8eb;border-radius:8px;padding:9px;flex:1}.filters input{flex-basis:160px}.mobile-applicants article{border-top:1px solid #e4ebf4}.mobile-applicants .applicant-row{border:0;background:none;border-radius:0;width:100%;padding:16px;display:flex;justify-content:flex-start;gap:13px;text-align:left}.applicant-row>span:last-child{flex:1;min-width:0}.mobile-applicants small{display:block;font-size:12px;color:#7589a2;margin-top:4px}.mobile-applicants .new{display:inline;margin-left:7px;color:#285fc5;background:#eaf2ff;border-radius:12px;padding:3px 7px}.mobile-applicants>p,.mobile-applicants>h3{padding:0 16px}.candidate-heading{display:flex;gap:14px;padding:16px}.candidate-heading h3{margin:0}.candidate-heading p{margin:4px 0;color:#6b829e}.candidate-actions{display:flex;flex-wrap:wrap;gap:7px;padding:0 16px 14px}.candidate-actions>*{max-width:100%;overflow-wrap:anywhere}.application{padding:16px}.application p{font-size:13px}:focus-visible{outline:3px solid #80a7ed;outline-offset:2px}
</style>
